var strongsHebrewDictionary = {"H1":{"lemma":"אָב","xlit":"ʼâb","pron":"awb","derivation":"a primitive word;","strongs_def":"father, in a literal and immediate, or figurative and remote application","kjv_def":"chief, (fore-) father(-less), [idiom] patrimony, principal. Compare names in 'Abi-'."},"H430":{"lemma":"אֱלֹהִים","xlit":"ʼĕlôhîym","pron":"el-o-heem'","derivation":"plural of H433 (אֱלוֹהַּ);","strongs_def":"gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative","kjv_def":"angels, [idiom] exceeding, God (gods) (-dess, -ly), [idiom] (very) great, judges, [idiom] mighty."},"H853":{"lemma":"אֵת","xlit":"ʼêth","pron":"ayth","derivation":"apparent contracted from H226 (אוֹת) in the demonstrative sense of entity;","strongs_def":"properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely)","kjv_def":"(as such unrepresented in English)."},"H1254":{"lemma":"בָּרָא","xlit":"bârâʼ","pron":"baw-raw'","derivation":"a primitive root;","strongs_def":"(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes)","kjv_def":"choose, create (creator), cut down, dispatch, do, make (fat)."},"H7225":{"lemma":"רֵאשִׁית","xlit":"rêʼshîyth","pron":"ray-sheeth'","derivation":"from the same as H7218 (רֹאשׁ);","strongs_def":"the first, in place, time, order or rank (specifically, a firstfruit)","kjv_def":"beginning, chief(-est), first(-fruits, part, time), principal thing."},"H8674":{"lemma":"תַּתְּנַי","xlit":"Tattᵉnay","pron":"tat-ten-ah'-ee","derivation":"of foreign derivation;","strongs_def":"Tattenai, a Persian","kjv_def":"Tatnai."}};
